  ('vocab-import-62d20e335819afdd7b23fec7', 'constringe', '/kənˈstrɪndʒ/', 'Rút lại, thắt, siết, làm co lại.', 'become tight or as if tight', 'verb', 'The band can constringe the tube.', 'Nghĩa trong ngữ cảnh: Rút lại, thắt, siết, làm co lại.', 'Body parts', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-b93d30f6db06e27e8ac21e52', 'convoke', 'kɑnˈvoʊk', 'Triệu tập, đòi đến, mời đến.', 'call together', 'verb', 'They convoke the national assembly every year.', 'Nghĩa trong ngữ cảnh: Triệu tập, đòi đến, mời đến.', 'Actions and movement', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
