  ('vocab-import-d0c6d41dedffdf7e64eaf0a4', 'culpable', 'ˈkəlpəbəl', 'Đáng khiển trách; có tội; tội lỗi.', 'deserving blame or censure as being wrong or evil or injurious', 'adjective', 'It was culpable to ignore the warning.', 'Nghĩa trong ngữ cảnh: Đáng khiển trách; có tội; tội lỗi.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-568fb0e9b1e424a4b608a773', 'debilitate', 'dəˈbɪləˌteɪt', 'Làm yếu sức.', 'make weak', 'verb', 'The illness can debilitate older people.', 'Nghĩa trong ngữ cảnh: Làm yếu sức.', 'Health and medicine', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-e4e9751395bb2da42831b71b', 'decode', 'dɪˈkoʊd', 'Đọc (mật mã), giải (mã).', 'convert code into ordinary language', 'verb', 'I can decode this message with a key.', 'Nghĩa trong ngữ cảnh: Đọc (mật mã), giải (mã).', 'Technology', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-9d64f0db58e6654af250c9a9', 'deject', 'dɪˈʤɛkt', 'Làm buồn nản, làm chán nản; làm thất vọng.', 'lower someone''s spirits; make downhearted', 'verb', 'Bad news can deject even careful students.', 'Nghĩa trong ngữ cảnh: Làm buồn nản, làm chán nản; làm thất vọng.', 'Emotions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-24618f36379facaa2324dd17', 'deleterious', 'ˌdɛləˈtɪriəs', 'Có hại, độc.', 'harmful to living things', 'adjective', 'Too much smoke can be deleterious to health.', 'Nghĩa trong ngữ cảnh: Có hại, độc.', 'Health and medicine', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-cb8b7fddeb841e3d7e1fb3d4', 'demagogue', 'ˈdɛməˌgɑg', 'Kẻ mị dân.', 'a political leader who seeks support by appealing to popular passions and prejudices', 'noun', 'The demagogue promised easy answers to everyone.', 'Nghĩa trong ngữ cảnh: Kẻ mị dân.', 'People', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
