  ('vocab-import-743429b805238d5fe4509662', 'sluggishly', 'sˈləgɪʃli', 'Chậm chạp, không nhanh nhẹn, không hoạt bát; uể oải, lờ đờ, lờ phờ.', 'in a sluggish manner', 'adverb', 'The old man moved sluggishly across the room.', 'Nghĩa trong ngữ cảnh: Chậm chạp, không nhanh nhẹn, không hoạt bát; uể oải, lờ đờ, lờ phờ.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-2cd7795d68a9549542a219d1', 'sociologically', '/ˌsoʊsiəˈlɑːdʒɪkəlli/', 'Xã hội học; có liên quan đến xã hội học.', 'with regard to sociology', 'adverb', 'She spoke sociologically during the meeting.', 'Nghĩa trong ngữ cảnh: Xã hội học; có liên quan đến xã hội học.', 'Society and politics', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
