  ('vocab-import-36064282afd327bb4c4bf569', 'prevaricate', 'prəˈvɛrəkeɪt', 'nói thoái thác, nói quanh co; làm quanh co.', 'be deliberately ambiguous or unclear in order to mislead or withhold information', 'verb', 'Please do not prevaricate about your mistake.', 'Nghĩa trong ngữ cảnh: nói thoái thác, nói quanh co; làm quanh co.', 'Actions and movement', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-c9b3143407d772532928af3e', 'proclivity', 'proʊˈklɪvəti', 'Khuynh hướng, xu hướng, sự thiên về, sự ngả về.', 'a natural inclination', 'noun', 'She showed a procliviti for quiet work.', 'Nghĩa trong ngữ cảnh: Khuynh hướng, xu hướng, sự thiên về, sự ngả về.', 'Emotions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
