  ('vocab-import-d6d93d00ec29c23ad1daedc6', 'protuberant', '/prəˈtjuːbərənt/', 'Lồi lên, nhô lên, u lên.', 'curving outward', 'adjective', 'The protuberant stone caught my eye.', 'Nghĩa trong ngữ cảnh: Lồi lên, nhô lên, u lên.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-3be1a45d783c0a202fd9bb00', 'prude', 'prud', 'Người đàn bà làm ra bộ đoan trang kiểu cách.', 'a person excessively concerned about propriety and decorum', 'noun', 'She was a prude about loud jokes.', 'Nghĩa trong ngữ cảnh: Người đàn bà làm ra bộ đoan trang kiểu cách.', 'People', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-cf39f29581cf452f07955303', 'prudish', 'ˈprudɪʃ', 'Dễ bị xúc phạm, sốc, đặc biệt bằng những hình ảnh, lời nói... liên quan tới chuyện tình dục', 'exaggeratedly proper', 'adjective', 'He seemed prudish about that joke.', 'Nghĩa trong ngữ cảnh: Dễ bị xúc phạm, sốc, đặc biệt bằng những hình ảnh, lời nói... liên quan tới chuyện tình dục', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-9a76680baa41551455e52246', 'putative', 'ˈpjutətɪv', 'Giả định là, được cho là, được coi là.', 'purported; commonly put forth or accepted as true on inconclusive grounds', 'adjective', 'He is the putative leader of the group.', 'Nghĩa trong ngữ cảnh: Giả định là, được cho là, được coi là.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
