  ('vocab-import-5ed62a61d20138288ee914ad', 'pulchritude', '/ˈpʌlkrɪtjuːd/', 'Vẻ đẹp.', 'physical beauty (especially of a woman)', 'noun', 'Her pulchritude drew quiet praise.', 'Nghĩa trong ngữ cảnh: Vẻ đẹp.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-2aa9838c3263a53a763f7931', 'punctilious', 'pəŋkˈtɪliəs', 'Chú ý đến những chi tiết tỉ mỉ, hay hình thức vụn vặt, kỹ tính, câu nệ.', 'marked by precise accordance with details', 'adjective', 'She is punctilious about every small detail.', 'Nghĩa trong ngữ cảnh: Chú ý đến những chi tiết tỉ mỉ, hay hình thức vụn vặt, kỹ tính, câu nệ.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-95d1c970f69365e7cf292342', 'purloin', 'pərˈlɔɪn', 'Ăn cắp, xoáy, ăn trộm.', 'make off with belongings of others', 'verb', 'Someone tried to purloin my wallet at lunch.', 'Nghĩa trong ngữ cảnh: Ăn cắp, xoáy, ăn trộm.', 'Actions and movement', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-71a96ad66451e3411c984064', 'pusillanimous', 'pjusəˈlænəməs', 'Nhát gan, hèn nhát; nhu nhược, yếu hèn.', 'lacking in courage and manly strength and resolution; contemptibly fearful', 'adjective', 'His pusillanimous reply showed he feared the challenge.', 'Nghĩa trong ngữ cảnh: Nhát gan, hèn nhát; nhu nhược, yếu hèn.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-475493013719fd89e1798d8e', 'ramshackle', 'ˈræmˌʃækəl', 'Xiêu vẹo, đổ nát.', 'in deplorable condition', 'adjective', 'They live in a very ramshackle house near the woods.', 'Nghĩa trong ngữ cảnh: Xiêu vẹo, đổ nát.', 'Home and household', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-bcdd50cc47fad95e55755509', 'recant', 'riˈkænt', 'Công khai, rút lui và từ bỏ; công khai rút (ý kiến... ).', 'formally reject or disavow a formerly held belief, usually under pressure', 'verb', 'He recanted his old opinion in public.', 'Nghĩa trong ngữ cảnh: Công khai, rút lui và từ bỏ; công khai rút (ý kiến... ).', 'Actions and movement', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
