  ('vocab-import-235cb6757cb534c100b8a26b', 'refulgent', '/rɪˈfʌldʒənt/', 'Chói lọi, rực rỡ, huy hoàng.', 'radiating or as if radiating light', 'adjective', 'The sunset looked refulgent over the lake.', 'Nghĩa trong ngữ cảnh: Chói lọi, rực rỡ, huy hoàng.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-e37ed9d1e2b15149ff7269be', 'appreciatively', 'əˈpriʃjətɪvli', 'Khen ngợi, tán dương, tán thưởng.', 'with appreciation; in a grateful manner', 'adverb', 'She spoke appreciatively during the meeting.', 'Nghĩa trong ngữ cảnh: Khen ngợi, tán dương, tán thưởng.', 'Actions and movement', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-08acd826d8e5cc7e1897b87d', 'repine', '/rɪˈpɑɪn/', 'Phàn nàn, than phiền, cằn nhằn, không bằng lòng.', 'express discontent', 'verb', 'Do not repine about your current situation.', 'Nghĩa trong ngữ cảnh: Phàn nàn, than phiền, cằn nhằn, không bằng lòng.', 'Emotions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
